CREATE EXTENSION IF NOT EXISTS postgis;
CREATE TABLE IF NOT EXISTS stations (id TEXT PRIMARY KEY, name TEXT NOT NULL, district TEXT, location GEOGRAPHY(POINT,4326), source_status TEXT DEFAULT 'PLANNED');
CREATE TABLE IF NOT EXISTS aq_observations (id BIGSERIAL PRIMARY KEY, station_id TEXT REFERENCES stations(id), observed_at TIMESTAMPTZ NOT NULL, pm25 DOUBLE PRECISION, pm10 DOUBLE PRECISION, o3 DOUBLE PRECISION, nox DOUBLE PRECISION, source TEXT, quality_flag TEXT);
CREATE TABLE IF NOT EXISTS met_observations (id BIGSERIAL PRIMARY KEY, station_id TEXT REFERENCES stations(id), observed_at TIMESTAMPTZ NOT NULL, t2m DOUBLE PRECISION, t925 DOUBLE PRECISION, pblh DOUBLE PRECISION, wind_speed DOUBLE PRECISION, source TEXT);
CREATE TABLE IF NOT EXISTS forecast_runs (id UUID PRIMARY KEY, initialized_at TIMESTAMPTZ NOT NULL, provider TEXT NOT NULL, model_version TEXT, mode TEXT NOT NULL, metadata JSONB DEFAULT '{}');
CREATE TABLE IF NOT EXISTS aq_forecasts (run_id UUID REFERENCES forecast_runs(id), station_id TEXT REFERENCES stations(id), valid_at TIMESTAMPTZ, horizon_hours SMALLINT, pm25_p10 DOUBLE PRECISION, pm25_p50 DOUBLE PRECISION, pm25_p90 DOUBLE PRECISION, o3 DOUBLE PRECISION, aqi INTEGER, PRIMARY KEY(run_id, station_id, valid_at));
CREATE TABLE IF NOT EXISTS met_forecasts (run_id UUID REFERENCES forecast_runs(id), station_id TEXT REFERENCES stations(id), valid_at TIMESTAMPTZ, isi DOUBLE PRECISION, pblh DOUBLE PRECISION, ventilation_coefficient DOUBLE PRECISION, raw_pblh DOUBLE PRECISION, corrected_pblh DOUBLE PRECISION, PRIMARY KEY(run_id, station_id, valid_at));
CREATE TABLE IF NOT EXISTS fire_events (id TEXT PRIMARY KEY, detected_at TIMESTAMPTZ, location GEOGRAPHY(POINT,4326), frp DOUBLE PRECISION, source TEXT, data_status TEXT);
CREATE TABLE IF NOT EXISTS smoke_influence (run_id UUID REFERENCES forecast_runs(id), fire_id TEXT REFERENCES fire_events(id), station_id TEXT REFERENCES stations(id), valid_at TIMESTAMPTZ, sii DOUBLE PRECISION, eta_hours DOUBLE PRECISION, PRIMARY KEY(run_id, fire_id, station_id, valid_at));
CREATE TABLE IF NOT EXISTS verification_scores (model TEXT, pollutant TEXT, horizon_hours SMALLINT, start_at TIMESTAMPTZ, end_at TIMESTAMPTZ, mae DOUBLE PRECISION, rmse DOUBLE PRECISION, bias DOUBLE PRECISION, f1_high_aqi DOUBLE PRECISION, interval_coverage DOUBLE PRECISION, dataset_version TEXT, PRIMARY KEY(model,pollutant,horizon_hours,start_at));
CREATE TABLE IF NOT EXISTS model_registry (model_name TEXT, version TEXT, provider TEXT, status TEXT, model_card TEXT, registered_at TIMESTAMPTZ DEFAULT now(), PRIMARY KEY(model_name,version));
